import api from "./api";

const ROLES_PREFIX = "/api/v1/roles";
const PERMISSIONS_PREFIX = "/api/v1/permissions";

const getRoles = async () => {
  const response = await api.get(`${ROLES_PREFIX}/`);
  return response.data;
};

const getRole = async (roleId) => {
  const response = await api.get(`${ROLES_PREFIX}/${roleId}`);
  return response.data;
};

/**
 * payload: { name, description, is_company_scoped, permission_ids }
 */
const createRole = async (payload) => {
  const response = await api.post(`${ROLES_PREFIX}/`, payload);
  return response.data;
};

const updateRole = async (roleId, payload) => {
  const response = await api.put(`${ROLES_PREFIX}/${roleId}`, payload);
  return response.data;
};

const deleteRole = async (roleId) => {
  await api.delete(`${ROLES_PREFIX}/${roleId}`);
};

const getPermissions = async () => {
  const response = await api.get(`${PERMISSIONS_PREFIX}/`);
  return response.data;
};

const roleService = {
  getRoles,
  getRole,
  createRole,
  updateRole,
  deleteRole,
  getPermissions,
};

export default roleService;
